def verify_latest_response(latest_response):
    import re
    try:
        items = latest_response.get('Search', [])
        if not items:
            return 0
        pattern = re.compile(r'^https?://', re.IGNORECASE)
        checked = False
        for item in items:
            poster = item.get('Poster')
            if poster is None or poster == 'N/A':
                continue
            checked = True
            if not pattern.match(str(poster)):
                return -1
        if not checked:
            return 0
        return 1
    except:
        return 0

